-- All identities, PDF metadata, evaluations and source rows here are synthetic, never production data.
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',false);
select public.test_assert((public.iq_supplier_audit_context()->>'canManage')::boolean=false,'administrator does not automatically become inspector');
select public.test_denied($q$select public.iq_supplier_audit_save(null,0,'{"supplierId":"20000000-0000-4000-8000-000000000001","year":2026,"month":11,"precision":"date","plannedDate":"2026-11-10"}',null)$q$,'AUDIT_INSPECTOR_REQUIRED','unassigned administrator cannot program');
select public.iq_supplier_audit_configure(array['10000000-0000-4000-8000-000000000007'::uuid],array['20000000-0000-4000-8000-000000000003'::uuid],0,'Explicit synthetic scope verification');
select public.test_assert((select count(*) from public.organizations where id='20000000-0000-4000-8000-000000000003' and owning_organization_id is null)=1,'legacy scope confirmation does not reassign ownership');
select public.test_denied($q$select public.iq_supplier_audit_configure(array['10000000-0000-4000-8000-000000000002'::uuid],array[]::uuid[],1,'Invalid read only assignment')$q$,'AUDIT_INSPECTOR_PERMISSION_REQUIRED','view-only user cannot be configured as inspector');
select public.test_denied($q$select public.iq_supplier_audit_configure(array['10000000-0000-4000-8000-000000000007'::uuid],array[]::uuid[],0,'Stale configuration request')$q$,'AUDIT_CONFLICT','configuration has optimistic concurrency');
reset role;
create temporary table audit_fixture_ids(label text,id uuid);
grant all on audit_fixture_ids to authenticated;
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000007',false);
select public.test_assert((public.iq_supplier_audit_context()->>'canManage')::boolean,'assigned identity with update permission can manage');
insert into audit_fixture_ids select 'main',public.iq_supplier_audit_save(null,0,'{"supplierId":"20000000-0000-4000-8000-000000000001","year":2026,"month":11,"precision":"week","weekStart":"2026-11-09","state":"scheduled","criteria":"Synthetic criteria","responsible":"Synthetic inspector"}',null);
select public.test_assert((select count(*) from public.supplier_audit_events)=1,'week scheduling does not invent an exact date or result');
select public.test_denied($q$select public.iq_supplier_audit_save(null,0,'{"supplierId":"20000000-0000-4000-8000-000000000002","year":2026,"month":11,"precision":"month","state":"scheduled"}',null)$q$,'AUDIT_SUPPLIER_SCOPE_UNVERIFIED','inspector cannot program another organizations supplier');
select public.test_denied($q$select public.iq_supplier_audit_save(null,0,'{"supplierId":"20000000-0000-4000-8000-000000000001","year":2026,"month":11,"precision":"week","weekStart":"2026-11-09","state":"confirmed"}',null)$q$,'AUDIT_EXACT_DATE_REQUIRED','confirmed visits require definitive date');
select public.iq_supplier_audit_save(null,0,'{"supplierId":"20000000-0000-4000-8000-000000000001","year":2026,"month":11,"precision":"month","state":"scheduled"}',null) from generate_series(1,5);
select public.test_assert((select count(*) from public.supplier_audit_events where calendar_year=2026 and calendar_month=11)=6,'no artificial monthly four-audit limit');
select public.test_denied($q$select public.iq_supplier_audit_save((select id from audit_fixture_ids where label='main'),1,'{"supplierId":"20000000-0000-4000-8000-000000000001","year":2026,"month":11,"precision":"date","plannedDate":"2026-11-11","state":"cancelled"}','')$q$,'AUDIT_REASON_REQUIRED','cancellation requires reason');
select public.iq_supplier_audit_save((select id from audit_fixture_ids where label='main'),1,'{"supplierId":"20000000-0000-4000-8000-000000000001","year":2026,"month":11,"precision":"date","plannedDate":"2026-11-11","state":"rescheduled"}','Supplier requested another date');
select public.test_assert((select revision=2 and planned_date='2026-11-11' and week_start is null from public.supplier_audit_events where id=(select id from audit_fixture_ids where label='main')),'reprogramming persists with one identity and revised date');
select public.test_denied($q$select public.iq_supplier_audit_save((select id from audit_fixture_ids where label='main'),1,'{"supplierId":"20000000-0000-4000-8000-000000000001","year":2026,"month":11,"precision":"date","plannedDate":"2026-11-11","state":"cancelled"}','Concurrent stale revision')$q$,'AUDIT_CONFLICT','stale schedule update rejected');
select public.test_denied($q$select public.iq_supplier_audit_save((select id from audit_fixture_ids where label='main'),2,'{"supplierId":"20000000-0000-4000-8000-000000000001","year":2026,"month":11,"precision":"date","plannedDate":"2026-11-11","actualDate":"2026-01-05","state":"performed"}','Attempt without PDF evidence')$q$,'AUDIT_ACTUAL_DATE_AND_REPORT_REQUIRED','actual realization requires verifiable PDF');
select public.test_denied($q$select public.iq_supplier_audit_configure(array[]::uuid[],array[]::uuid[],1,'Inspector cannot configure')$q$,'AUDIT_ADMIN_REQUIRED','inspector cannot grant scope or assign identities');
reset role;
-- An actual private-object row is required by the file-registration RPC.
insert into storage.objects(bucket_id,name,metadata) select 'integraq-private','10000000-0000-4000-8000-000000000007/supplier-audits/'||id||'/synthetic-report.pdf','{"size":128,"mimetype":"application/pdf"}' from audit_fixture_ids where label='main';
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000007',false);
insert into audit_fixture_ids select 'report',public.iq_supplier_audit_file(id,2,jsonb_build_object('type','supplier_audit_report','path','10000000-0000-4000-8000-000000000007/supplier-audits/'||id||'/synthetic-report.pdf','mime','application/pdf','name','Synthetic report.pdf','size',128,'sha256',repeat('a',64),'reason','Synthetic verified report')) from audit_fixture_ids where label='main';
select public.test_assert((select revision=3 and actual_date is null from public.supplier_audit_events where id=(select id from audit_fixture_ids where label='main')),'upload time does not become realization date');
insert into audit_fixture_ids select 'result',public.iq_supplier_audit_result((select id from audit_fixture_ids where label='main'),3,jsonb_build_object('questionnaire','manufacturers','scores',(select jsonb_object_agg(i::text,80) from generate_series(1,9) i),'score',72.5,'evaluationDate','2026-01-06','actualDate','2026-01-05','auditor','Synthetic auditor','reportId',(select id from audit_fixture_ids where label='report')),true,'Manual verified final grade');
select public.test_assert((select score=72.5 and (select count(*) from jsonb_object_keys(rubric_scores))=9 and portal_visible=false and source_file_id is null from public.supplier_assessments where id=(select id from audit_fixture_ids where label='result')),'manual final score preserved without averaging nine rubrics or publishing');
select public.test_assert((select state='completed' and actual_date='2026-01-05' and planned_date='2026-11-11' from public.supplier_audit_events where id=(select id from audit_fixture_ids where label='main')),'programmed date actual date and finalization remain distinct');
with changed as (update public.supplier_assessments set score=100 where id=(select id from audit_fixture_ids where label='result') returning id) select public.test_assert((select count(*)=0 from changed),'direct result update cannot bypass inspector RPC');
select public.test_denied($q$select public.iq_supplier_audit_result((select id from audit_fixture_ids where label='main'),4,jsonb_build_object('questionnaire','distributors','scores','{"1":100}'::jsonb,'score',100),true,'Missing required rubrics')$q$,'AUDIT_SCORES_INVALID','partial questionnaires cannot finalize');
select public.iq_supplier_audit_contacts('20000000-0000-4000-8000-000000000003','{"qualityName":"Synthetic quality contact","notificationName":"Synthetic receiver","email":"recipient@example.test","emailVerified":true,"phone":"000000"}',(select updated_at from public.organizations where id='20000000-0000-4000-8000-000000000003'),'Verified contact in isolated fixture');
select public.test_assert((select code='LEGACY-SYNTHETIC' and owning_organization_id is null and metadata->'supplierQualityContacts'->>'emailVerified'='true' from public.organizations where id='20000000-0000-4000-8000-000000000003'),'contact verification preserves official code and ownership');
select public.test_denied($q$select public.iq_supplier_audit_contacts('20000000-0000-4000-8000-000000000002','{}',now(),'Foreign supplier write')$q$,'AUDIT_SUPPLIER_SCOPE_UNVERIFIED','contact editing rejects another organization');
select public.test_denied($q$select public.iq_supplier_audit_contacts('20000000-0000-4000-8000-000000000003','{"emailVerified":true}',(select updated_at from public.organizations where id='20000000-0000-4000-8000-000000000003'),'No verified recipient')$q$,'AUDIT_CONFIRMED_RECIPIENT_REQUIRED','verification requires real recipient name and email');
select public.test_assert((select count(*)>0 from public.audit_log where resource_type='supplier_assessment' and resource_id=(select id::text from audit_fixture_ids where label='result') and organization_id is null),'own organization can read legacy log rows through actual assessment identity');
select public.test_denied($q$insert into public.audit_log(actor_id,resource_type,resource_id,action,organization_id) values(auth.uid(),'supplier_audit_event','forged','fake','00000000-0000-4000-8000-000000000001')$q$,'row-level security','direct requests cannot fabricate managed audit log entries');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'integraq-private','10000000-0000-4000-8000-000000000007/supplier-audits/'||id||'/synthetic-report-v2.pdf','{"size":128,"mimetype":"application/pdf"}' from audit_fixture_ids where label='main';
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000007',false);
insert into audit_fixture_ids select 'report-v2',public.iq_supplier_audit_file(id,4,jsonb_build_object('type','supplier_audit_report','path','10000000-0000-4000-8000-000000000007/supplier-audits/'||id||'/synthetic-report-v2.pdf','mime','application/pdf','name','Synthetic report v2.pdf','size',128,'sha256',repeat('b',64),'reason','Corrected synthetic PDF')) from audit_fixture_ids where label='main';
select public.test_assert((select audit_report_file_id=(select id from audit_fixture_ids where label='report') from public.supplier_assessments where id=(select id from audit_fixture_ids where label='result')),'uploading v2 does not silently replace the report attached to a finalized grade');
select public.iq_supplier_audit_result((select id from audit_fixture_ids where label='main'),5,jsonb_build_object('questionnaire','manufacturers','scores',(select jsonb_object_agg(i::text,80) from generate_series(1,9) i),'score',72.5,'evaluationDate','2026-01-06','actualDate','2026-01-05','auditor','Synthetic auditor','reportId',(select id from audit_fixture_ids where label='report-v2')),true,'Explicit verified report correction');
with removed as(delete from public.file_objects where resource_type='supplier_audit_report' returning id) select public.test_assert((select count(*)=0 from removed),'direct physical deletion of current or historical audit PDFs is blocked');
reset role;
select public.test_assert((select count(*)=2 and count(*) filter(where is_current)=1 from public.file_objects where resource_type='supplier_audit_report'),'one current PDF and all previous versions retained');
select public.test_assert((select count(*)=1 from public.supplier_assessments),'result correction never duplicates the audit evaluation');
-- Historical fixture: 22 unique source positions, original P/R and state retained.
create temporary table audit_import_fixture as select jsonb_agg(jsonb_build_object('supplierName','Synthetic historical supplier '||i,'supplierId',null,'year',2025,'month',8,'plannedDate','2025-08-10','actualDate',case when i<=14 then '2025-08-11' else null end,'state',case when i<=14 then 'performed' when i<=17 then 'cancelled' else 'pending' end,'sourceSheet',case when i<=7 then '2025 JUL-ENE' when i<=15 then '2026 FEB-JUL' else '2026 AGO-ENE' end,'sourceRow',12+3*(case when i<=7 then i-1 when i<=15 then i-8 else i-16 end),'sourceColumn','X','sourceStatus',case when i<=14 then null when i<=17 then 'Cancelada' else 'PENDIENTE' end,'criteria','Synthetic source criteria','method','Synthetic source method','responsible','Synthetic source responsible','sourcePayload',jsonb_build_object('rowValues',(select jsonb_agg(0) from generate_series(1,35)),'plannedValue',45879,'actualValue',case when i<=14 then '45880' when i<=17 then 'Cancelada' else 'PENDIENTE' end))) as rows from generate_series(1,22) i;
grant select on audit_import_fixture to authenticated;
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000007',false);
select public.iq_supplier_audit_import('28f5784c76c2cb077f9d0aae69c8de10175f2c66f7b1ad130c98e7261ff164df',(select rows from audit_import_fixture));
select public.test_assert((select count(*)=22 and count(*) filter(where actual_date is not null)=14 and count(*) filter(where state='cancelled')=3 and count(*) filter(where state='pending')=5 from public.supplier_audit_events where source_sha256 is not null),'22 historical entries preserve dates cancellations and pending states');
select public.test_assert((select count(*)=1 from public.supplier_assessments),'historical date R does not create an evaluation or PDF');
select public.iq_supplier_audit_import('28f5784c76c2cb077f9d0aae69c8de10175f2c66f7b1ad130c98e7261ff164df',(select rows from audit_import_fixture));
select public.test_assert((select count(*)=22 from public.supplier_audit_events where source_sha256 is not null),'repeat import is idempotent');
select public.test_denied($q$select public.iq_supplier_audit_import('wrong',(select rows from audit_import_fixture))$q$,'AUDIT_SOURCE_INVALID','wrong source rejected transactionally');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
select public.test_assert((select count(*)=28 from public.supplier_audit_events),'authorized internal user can consult own organization');
select public.test_denied($q$select public.iq_supplier_audit_save(null,0,'{}',null)$q$,'AUDIT_INSPECTOR_REQUIRED','internal view-only user cannot create');
select public.test_denied($q$select public.iq_supplier_audit_file((select id from audit_fixture_ids where label='main'),4,'{}')$q$,'AUDIT_INSPECTOR_REQUIRED','internal view-only user cannot upload');
select public.test_denied($q$select public.iq_supplier_audit_result((select id from audit_fixture_ids where label='main'),4,'{}',true,'Unauthorized result')$q$,'AUDIT_INSPECTOR_REQUIRED','internal view-only user cannot finalize');
select public.test_assert((select count(*)=0 from public.file_objects where resource_type='supplier_audit_report'),'private PDFs are never exposed by broad direct select');
select public.test_assert((select count(*)=0 from storage.objects where name like '%/supplier-audits/%'),'private PDF objects cannot be accessed directly');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000005',false);
select public.test_assert((select count(*)=0 from public.supplier_audit_events),'administrator from organization B cannot read A');
select public.test_assert((select count(*)=0 from public.supplier_assessments where audit_event_id is not null),'legacy permissive assessment select does not expose managed results across organizations');
select public.test_assert((select count(*)=0 from public.audit_log where resource_type in ('supplier_audit_event','supplier_assessment')),'legacy OR log policy does not expose managed logs or null-organization legacy result logs across organizations');
select public.test_denied($q$select public.iq_supplier_audit_result((select id from audit_fixture_ids where label='main'),4,'{}',true,'Cross organization write')$q$,'AUDIT_INSPECTOR_REQUIRED','other organization administrator cannot write');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',false);
select public.test_assert((select count(*)=0 from public.supplier_audit_events),'supplier portal not activated by scheduling');
select public.test_assert((select count(*)=0 from public.supplier_assessments where audit_event_id is not null),'supplier cannot access unpublished grades');
select public.test_assert((select count(*)=0 from public.audit_log where resource_type in ('supplier_audit_event','supplier_assessment')),'supplier cannot query internal audit logs');
select public.test_denied($q$select public.iq_supplier_audit_context()$q$,'AUDIT_ACCESS_DENIED','supplier denied internal API context');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',false);
select public.test_assert((select count(*)=0 from public.supplier_audit_events),'customer portal remains separate');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000006',false);
select public.test_denied($q$select public.iq_supplier_audit_context()$q$,'AUDIT_ACCESS_DENIED','inactive administrator rejected');
reset role;
select public.test_assert((select count(*)=0 from public.notifications) and (select count(*)=0 from public.integration_outbox),'no real notifications from audit creation import or finalization');
select public.test_assert((select count(*)=8 from public.profiles) and (select count(*)=5 from public.organizations),'no accounts created or company identities replaced');
select public.test_assert((select count(*)>=1 from public.audit_log where action='audit.rescheduled' and previous_value is not null and reason is not null),'rescheduling audit trail retains prior values and reason');
select public.test_assert((select count(*)>=1 from public.audit_log where action='audit.completed' and new_value->>'score'='72.5'),'manual final score has audit trace');
-- A stable synthetic target for the runner's two simultaneous update transactions.
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000007',false);
select public.iq_supplier_audit_save(null,0,'{"supplierId":"20000000-0000-4000-8000-000000000001","year":2040,"month":1,"precision":"month","state":"scheduled","criteria":"Concurrency target"}',null);
reset role;
